<div class="page-heading"><div><div class="eyebrow">GLOBAL TASK TEMPLATES</div><h1><?= $id?'Edit subtask template':'Create subtask template' ?></h1><p>Notes, photos, completion, and PM sign-off are available on every store step.</p></div><a class="button" href="<?= e(url('templates')) ?>">Back to templates</a></div>
<form class="panel user-form" method="post" action="<?= e(url('template-edit',$id?['id'=>$id]:[])) ?>"><?= csrf() ?><div class="form-grid"><label>Subtask title<input name="title" aria-label="Subtask title" maxlength="200" required value="<?= e($form['title']??'') ?>"></label><label>Workstream<select name="category" aria-label="Workstream"><?php foreach(ProjectRepository::CATEGORIES as $key=>$label): ?><option value="<?= e($key) ?>" <?= ($form['category']??'')===$key?'selected':'' ?>><?= e($label) ?></option><?php endforeach; ?></select></label><label class="wide">Instructions<textarea name="instructions" aria-label="Instructions" rows="5" maxlength="10000"><?= e($form['instructions']??'') ?></textarea></label></div><label class="checkbox-label"><input type="checkbox" name="active" <?= ($form['active']??false)?'checked':'' ?>>Include this subtask in new stores</label><div class="form-actions"><button class="button primary">Save template</button></div></form>
